            return True
        literal = next((l for l in range(1, len(cnf) + 1) if l not in assignment and -l not in assignment), None)
        if literal is None:
            return False

        def propagate(lit):
            new_cnf = []
            for clause in cnf:
                if lit in clause:
                    continue
                if -lit in clause:
                    clause.remove(-lit)
                    if not clause:
                        return False
                new_cnf.append(clause)
            return new_cnf, {**assignment, lit: True}

        def backtrack(lit):
            new_cnf = []
            for clause in cnf:
                if -lit in clause:
                    continue
                if lit in clause:
                    clause.remove(lit)
                    if not clause:
                        return False
                new_cnf.append(clause)
            return new_cnf, {**assignment, -lit: True}

        if propagate(literal):
            result = dpll(propagate(literal)[0], assignment)
